"""Tests for the asset-storage pipeline (no network, no database).

The point of these tests is the contract the image pipeline now depends on:

* generated bytes are validated before they are stored;
* a stored asset comes back as a URL string -- never as base64 in a row;
* when Supabase Storage is not configured or is unreachable, the caller gets a
  clear reason instead of an exception or a broken URL.
"""

from __future__ import annotations

import base64
from types import SimpleNamespace

import pytest

from app.core import storage

PNG_BYTES = base64.b64decode(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFAAH/q842iQAAAABJRU5ErkJggg=="
)
JPEG_BYTES = b"\xff\xd8\xff\xe0" + b"\x00" * 32
WEBP_BYTES = b"RIFF" + b"\x00\x00\x00\x00" + b"WEBP" + b"\x00" * 16


def _cfg(**overrides: object) -> SimpleNamespace:
    base = dict(
        upload_dir="/tmp/sahm-storage-test",
        public_asset_base_url="",
        api_prefix="/api/v1",
        upload_max_bytes=10 * 1024 * 1024,
        supabase_url=None,
        supabase_secret_key=None,
        supabase_publishable_key=None,
    )
    base.update(overrides)
    return SimpleNamespace(**base)


def _data_url(mime: str, payload: bytes) -> str:
    return f"data:{mime};base64,{base64.b64encode(payload).decode()}"


class TestSniffing:
    def test_recognises_the_supported_formats(self):
        assert storage.sniff_image_mime(PNG_BYTES) == "image/png"
        assert storage.sniff_image_mime(JPEG_BYTES) == "image/jpeg"
        assert storage.sniff_image_mime(WEBP_BYTES) == "image/webp"
        assert storage.sniff_image_mime(b"<svg xmlns='http://www.w3.org/2000/svg'></svg>") == "image/svg+xml"

    def test_rejects_anything_else(self):
        assert storage.sniff_image_mime(b"not an image at all") is None
        assert storage.sniff_image_mime(b"") is None


class TestPersistImageAsset:
    @pytest.mark.asyncio
    async def test_prefers_supabase_when_it_accepts_the_upload(self, monkeypatch, tmp_path):
        async def fake_upload(cfg, data, mime, *, bucket=storage.DEFAULT_BUCKET, path):
            assert data == PNG_BYTES
            assert mime == "image/png"
            return f"https://x.supabase.co/storage/v1/object/public/{bucket}/{path}"

        monkeypatch.setattr(storage, "upload_bytes", fake_upload)
        url, error = await storage.persist_image_asset(
            _cfg(upload_dir=str(tmp_path)), asset_url=_data_url("image/png", PNG_BYTES)
        )

        assert error is None
        assert url is not None and url.startswith("https://x.supabase.co/storage/v1/object/public/")
        assert "data:" not in url

    @pytest.mark.asyncio
    async def test_falls_back_to_local_disk_and_says_so(self, monkeypatch, tmp_path):
        async def no_upload(*args, **kwargs):
            return None

        monkeypatch.setattr(storage, "upload_bytes", no_upload)
        cfg = _cfg(upload_dir=str(tmp_path), public_asset_base_url="https://api.example.com")
        url, error = await storage.persist_image_asset(cfg, asset_url=_data_url("image/png", PNG_BYTES))

        assert error is None
        assert url == "https://api.example.com/api/v1/media/public-assets/" + url.rsplit("/", 1)[-1]
        assert (tmp_path / "public_assets").is_dir()

    @pytest.mark.asyncio
    async def test_without_storage_or_public_base_it_refuses(self, monkeypatch, tmp_path):
        async def no_upload(*args, **kwargs):
            return None

        monkeypatch.setattr(storage, "upload_bytes", no_upload)
        url, error = await storage.persist_image_asset(
            _cfg(upload_dir=str(tmp_path)), asset_url=_data_url("image/png", PNG_BYTES)
        )

        assert url is None
        assert error is not None and "PUBLIC_ASSET_BASE_URL" in error

    @pytest.mark.asyncio
    async def test_rejects_bytes_that_do_not_match_the_declared_type(self):
        url, error = await storage.persist_image_asset(
            _cfg(), asset_url=_data_url("image/png", JPEG_BYTES)
        )

        assert url is None
        assert error is not None and "declared file type" in error

    @pytest.mark.asyncio
    async def test_rejects_invalid_base64(self):
        url, error = await storage.persist_image_asset(_cfg(), asset_url="data:image/png;base64,@@@@")

        assert url is None
        assert error is not None

    @pytest.mark.asyncio
    async def test_enforces_the_size_cap(self):
        big = b"\x89PNG\r\n\x1a\n" + b"\x00" * 2048
        url, error = await storage.persist_image_asset(
            _cfg(upload_max_bytes=1024), asset_url=_data_url("image/png", big)
        )

        assert url is None
        assert error is not None and "size limit" in error


class TestSupabaseFailuresAreSurvivable:
    @pytest.mark.asyncio
    async def test_upload_to_an_unreachable_project_returns_none(self):
        cfg = _cfg(supabase_url="https://does-not-exist.invalid", supabase_secret_key="fake")

        assert await storage.upload_bytes(cfg, PNG_BYTES, "image/png", path="a/b.png") is None

    @pytest.mark.asyncio
    async def test_mirror_and_fetch_never_raise(self):
        cfg = _cfg(supabase_url="https://does-not-exist.invalid", supabase_secret_key="fake")

        assert await storage.mirror_private_asset(cfg, "reference_x.png", PNG_BYTES, "image/png") is False
        assert await storage.fetch_private_asset(cfg, "reference_x.png") is None

    def test_not_configured_without_both_halves(self):
        assert storage.is_supabase_configured(_cfg()) is False
        assert storage.is_supabase_configured(_cfg(supabase_url="https://x.supabase.co")) is False
        assert (
            storage.is_supabase_configured(
                _cfg(supabase_url="https://x.supabase.co", supabase_secret_key="k")
            )
            is True
        )
